// Self-destructing service worker.
//
// The previous Jekyll (Chirpy) version of this site registered a service
// worker at /sw.min.js with scope "/". The Astro rebuild deleted that file
// along with app.min.js, which held Chirpy's own unregister logic — so the
// worker was never told to remove itself. In browsers that visited between
// Jan and Jul 2026 it is still active, serving the old site from Cache
// Storage and ignoring HTTP cache headers entirely.
//
// This replacement takes over that registration, empties the caches, and
// unregisters itself. Safe to delete once enough time has passed that no
// stale registrations remain in the wild.

self.addEventListener("install", () => {
  // Activate immediately instead of waiting for existing tabs to close.
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((key) => caches.delete(key)));
      await self.registration.unregister();

      // Reload any open tabs so they pick up the live site.
      const clients = await self.clients.matchAll({ type: "window" });
      for (const client of clients) {
        client.navigate(client.url);
      }
    })()
  );
});
